<script setup lang="ts">
import { LayoutDashboard, House, Layers, FileText, BookOpen, ChevronLeft, ChevronRight, Menu, ArrowUpRight, Download, Search, SlidersHorizontal, RotateCcw, Upload, Building2 } from 'lucide-vue-next'
import { dimensions, lines, type Row } from './types/data'
import { format, integral, need, total, value, numeric } from './utils/analytics'
import { distribution, scatter } from './utils/charts'
const { dataset, loading, error, configured, filters, filtered, original, load, upload, applySchema, reset, downloadFiltered } = useTerritorialData()
const baseURL=useRuntimeConfig().app.baseURL
const sections = [
  { id: 'panorama', label: 'Panorama territorial', icon: LayoutDashboard, description: 'Explora las condiciones de los hogares y los registros de la CVP en cada territorio.' },
  { id: 'necesidad', label: 'Necesidad habitacional', icon: House, description: 'Conoce las necesidades de los hogares y cómo cambia el índice al dar más peso a cada tema.' },
  { id: 'presencia', label: 'Presencia misional', icon: Layers, description: 'Conoce qué registros publican las cinco líneas de la Caja de la Vivienda Popular.' },
  { id: 'ficha', label: 'Ficha territorial', icon: FileText, description: 'Conoce los datos de cada territorio, de dónde vienen y cómo leerlos.' },
  { id: 'metodologia', label: 'Metodología y fuentes', icon: BookOpen, description: 'Descubre de dónde vienen los datos, cómo los calculamos y qué puedes interpretar con ellos.' }
]
const readingGuideOpen=ref(false)
const active = ref('panorama'), collapsed = ref(false), mobileOpen = ref(false), page = ref(1), selected = ref(''), order = ref('name')
const menuSections = sections.filter(section => !['necesidad', 'presencia', 'ficha'].includes(section.id))
const current = computed(() => sections.find(s => s.id === active.value)!)
const schema = computed(() => dataset.value.schema)
const get = (r: Row, key: string) => value(r, schema.value, key)
const localities = computed(() => [...new Set(dataset.value.rows.map(r => get(r, 'localidad')).filter(v => v !== null))].map(String).sort())
const domains = computed(() => dataset.value.rows.filter(r => !filters.locality || String(get(r, 'localidad')) === filters.locality))
const sorted = computed(() => [...filtered.value].sort((a,b) => order.value === 'need' ? (need(b, dataset.value.rows, schema.value) ?? -1) - (need(a, dataset.value.rows, schema.value) ?? -1) : String(get(a, 'nombre')).localeCompare(String(get(b, 'nombre')), 'es')))
const pages = computed(() => Math.max(1, Math.ceil(sorted.value.length / 10)))
const shown = computed(() => sorted.value.slice((page.value-1)*10, page.value*10))
const territory = computed(() => filtered.value.find(r => String(get(r,'codigo')) === selected.value))
const availableLines = computed(() => lines.filter(l => total(filtered.value, schema.value, `registros_${l.key}`) !== null))
const singleLine = computed(() => filters.line || 'barrios')
const scatterReady = computed(() => filtered.value.some(r => need(r, dataset.value.rows, schema.value) !== null && numeric(get(r, `registros_${singleLine.value}`)) !== null))
const localityCount = computed(() => new Set(filtered.value.map(r => get(r,'localidad')).filter(v => v !== null)).size)
const completeLines = computed(() => filtered.value.filter(r => integral(r, schema.value) === 5).length)
watch(filters, () => { page.value=1; selected.value='' }, { deep: true })
watch(() => filters.locality, () => { filters.domain='' })
watch(order, () => { page.value=1 })
onMounted(() => { const hash = window.location.hash.slice(1); if (sections.some(s => s.id===hash)) active.value=hash; window.addEventListener('hashchange', onHash) })
onBeforeUnmount(() => window.removeEventListener('hashchange', onHash))
function onHash() { const hash = window.location.hash.slice(1); if (sections.some(s => s.id===hash)) active.value=hash }
function navigate(id: string) { active.value=id; mobileOpen.value=false; window.location.hash=id }
function select(code: string) { selected.value=code; navigate('ficha') }
async function onUpload(e: Event) { const file=(e.target as HTMLInputElement).files?.[0]; if (file) await upload(file); (e.target as HTMLInputElement).value='' }
</script>
<template>
  <a class="skip-link" href="#contenido">Saltar al contenido</a>
  <div class="app-shell reference-layout" :class="{ collapsed, 'mobile-open': mobileOpen }">
    <button v-if="mobileOpen" class="scrim" aria-label="Cerrar navegación" @click="mobileOpen=false"/>
    <aside class="sidebar" aria-label="Navegación principal">
      <a href="#panorama" class="brand" aria-label="UBiK2, panorama territorial" @click.prevent="navigate('panorama')"><img :src="`${baseURL}brand/ubik2.png`" alt="UBiK2" class="project-logo"><span class="logo-caption">OBSERVATORIO<br>TERRITORIAL</span></a>
      <div class="header-actions"><span class="status-pill">{{ dataset.status==='final' ? '95 TERRITORIOS · ARCHIVO FINAL' : 'DATOS PRELIMINARES' }}</span><button class="guide-cta" aria-haspopup="dialog" @click="readingGuideOpen=true"><BookOpen :size="18" aria-hidden="true"/><span>Empieza aquí · guía de uso</span><ChevronRight :size="16" aria-hidden="true"/></button></div>
      <div class="sidebar-divider"/><p class="nav-label">EXPLORAR EL OBSERVATORIO</p>
      <nav><a v-for="s in menuSections" :key="s.id" :href="`#${s.id}`" :class="{ active: active===s.id }" :aria-current="active===s.id ? 'page' : undefined" :title="s.label" @click.prevent="navigate(s.id)"><component :is="s.icon" :size="19"/><span>{{ s.label }}</span><ChevronRight v-if="active===s.id" :size="14" class="nav-arrow"/></a></nav>
      <div class="sidebar-bottom"><div class="institution"><span>CVP</span><p>Caja de la<br><strong>Vivienda Popular</strong></p></div><p class="sidebar-note">Datos para comprender<br>y transformar el territorio.</p><button class="collapse-button" :aria-label="collapsed ? 'Expandir barra lateral' : 'Plegar barra lateral'" :aria-expanded="!collapsed" @click="collapsed=!collapsed"><component :is="collapsed ? ChevronRight : ChevronLeft" :size="18"/><span>Plegar menú</span></button></div>
    </aside>
    <div class="workspace">
      <header v-if="active!=='panorama'" class="topbar"><div class="topbar-context"><button class="icon-button mobile-toggle" aria-label="Abrir navegación" @click="mobileOpen=true"><Menu :size="22"/></button><span>Observatorio territorial</span><span class="separator">/</span><strong>{{ current.label }}</strong></div><div class="topbar-right"><span class="status-pill"><i/>{{ dataset.status==='final' ? 'Archivo final · lectura exploratoria' : 'Exploración preliminar' }}</span><span class="city-label">BOGOTÁ, D. C.</span></div></header>
      <main id="contenido" tabindex="-1">
        <div v-if="active!=='panorama'" class="page-heading"><div><div class="section-label">UBiK2 / DATA JAM CVP 2026</div><h1>{{ current.label }}</h1><p>{{ current.description }}</p></div><button v-if="active!=='metodologia'" class="outline export" :disabled="!filtered.length" @click="downloadFiltered"><Download :size="16"/>Descargar resultados</button></div>
        <div v-if="active!=='panorama' && active!=='metodologia'" class="notice intro-notice"><span class="notice-symbol">i</span><p><strong>Antes de comparar, ten en cuenta:</strong> La necesidad se basa en la encuesta de 2021. Los registros de la CVP corresponden a años distintos y no indican qué proporción de hogares recibió atención.</p><a href="#metodologia" @click.prevent="navigate('metodologia')">Ver metodología <ArrowUpRight :size="15"/></a></div>
        <section v-if="active!=='panorama' && active!=='metodologia'" class="panel filter-panel" aria-label="Filtros territoriales"><div class="filter-heading"><span><SlidersHorizontal :size="16"/>Filtros de exploración</span><button class="text-button" @click="reset"><RotateCcw :size="14"/>Limpiar filtros</button></div><div class="filters"><label>Localidad<select aria-label="Localidad" v-model="filters.locality" :disabled="!configured"><option value="">Todas las localidades</option><option v-for="l in localities" :key="l">{{ l }}</option></select></label><label>Territorio de la encuesta<select aria-label="Territorio de la encuesta" v-model="filters.domain" :disabled="!configured"><option value="">Todos los territorios</option><option v-for="r in domains" :key="String(get(r,'codigo'))" :value="String(get(r,'codigo'))">{{ get(r,'nombre') }}</option></select></label><label>Línea de la CVP<select aria-label="Línea de la CVP" v-model="filters.line" :disabled="!configured"><option value="">Todas las líneas</option><option v-for="l in lines" :key="l.key" :value="l.key">{{ l.label }}</option></select></label><label>Buscar territorio<div class="search-input"><Search :size="16"/><input v-model="filters.search" :disabled="!configured" placeholder="Nombre o código"></div></label></div><p class="filter-note">Al elegir una línea, verás los territorios donde tiene al menos un registro publicado.</p></section>
        <div v-if="error" role="alert" class="notice error">{{ error }} <button class="text-button" @click="load">Volver a cargar los datos</button></div>
        <div v-if="loading" role="status" class="panel loading">Cargando datos territoriales…</div>
        <section v-else-if="!configured" class="panel data-pending"><div class="data-pending-icon"><Upload :size="23"/></div><div><h2>{{ dataset.rows.length ? 'Relaciona las columnas para empezar' : 'Carga tus datos para empezar' }}</h2><p>{{ dataset.rows.length ? 'Indica qué información contiene cada columna. El diccionario del archivo te puede ayudar.' : 'Todavía no hay datos disponibles para mostrar. Puedes cargar un archivo CSV para explorar tus propios datos.' }}</p></div><label class="upload-button">Cargar CSV<input type="file" accept=".csv,text/csv" @change="onUpload"></label></section>
        <SchemaMapper v-if="dataset.columns.length && !configured && active!=='metodologia'" :key="original" :dataset="dataset" @apply="applySchema"/>
        <ObservatoryOverview v-if="active==='panorama' && configured" :dataset="dataset" :rows="filtered" :filters="filters" :configured="configured" @update-filters="Object.assign(filters,$event)" @reset="reset" @select="select" @navigate="navigate"/>
        <AnalyticalModel v-if="dataset.status!=='final' && (active==='necesidad' || active==='metodologia')"/>
        <section v-if="active==='necesidad' && dataset.status==='final'" class="panel"><h2>Cómo resumimos la necesidad</h2><p>Reunimos cinco temas con el mismo peso: tenencia, vivienda, entorno, amenaza alta y vulnerabilidad. Todos se llevan a una escala comparable de 0 a 1 antes de promediarlos. Aquí conservamos los valores del archivo final.</p></section><section v-if="active==='necesidad' && dataset.status!=='final'" class="panel"><h2>¿Qué cambia si damos más peso a un tema?</h2><p>El archivo preliminar incluye tres formas de calcular la necesidad, en una escala de 0 a 100. Puedes compararlas para ver qué cambia al dar más peso a vivienda o a riesgo. Conservamos esos valores. Si cargas otro CSV, ajustamos la escala usando todos sus territorios y la dirección de necesidad que hayas indicado.</p><div class="weight-grid"><div><strong>Pesos iguales</strong><p>Tenencia 25% · vivienda 25%<br>entorno 25% · riesgo 25%</p></div><div><strong>Doble peso de vivienda</strong><p>Vivienda 40%<br>otras dimensiones 20% cada una</p></div><div><strong>Doble peso de riesgo</strong><p>Riesgo 40%<br>otras dimensiones 20% cada una</p></div></div><p class="muted">En este cálculo preliminar, pobreza y jefatura femenina ayudan a entender el contexto, pero no forman parte del índice. Los resultados no son una priorización oficial.</p><div class="table-scroll"><table><caption>Comparación de escenarios · valores de 0 a 100</caption><thead><tr><th>Territorio</th><th v-for="d in dimensions" :key="d">{{ d }}</th><th>Iguales</th><th>Vivienda ×2</th><th>Riesgo ×2</th><th>Pobreza</th><th>Jefatura femenina</th></tr></thead><tbody><tr v-for="r in shown" :key="String(get(r,'codigo'))"><th>{{ get(r,'nombre') }}</th><td v-for="d in dimensions" :key="d">{{ format(get(r,d)) }}</td><td>{{ format(need(r,dataset.rows,schema)) }}</td><td>{{ format(need(r,dataset.rows,schema,'housing')) }}</td><td>{{ format(need(r,dataset.rows,schema,'risk')) }}</td><td>{{ format(get(r,'pobreza')) }}</td><td>{{ format(get(r,'jefatura')) }}</td></tr></tbody></table></div></section>
        <section v-if="active==='presencia'" class="panel"><h2>¿Qué registra cada línea de la CVP?</h2><p>Cada línea cuenta cosas distintas. En las fichas puedes ver sus registros, tasas y actuaciones confirmadas. Si un código no tiene una explicación verificada, lo mostramos sin interpretarlo.</p><div class="line-grid"><article v-for="line in lines.filter(l=>!filters.line || l.key===filters.line)" :key="line.key"><span class="line-dot" :style="{ background: line.color }"/><h3>{{ line.label }}</h3><strong>{{ format(total(filtered,schema,`registros_${line.key}`)) }}</strong><small>Total de registros con dato disponible</small><p>{{ filtered.filter(r=>numeric(get(r,`registros_${line.key}`))!==null).length }} de {{ filtered.length }} territorios con dato</p></article></div><PublishedHousing v-if="dataset.analysis && (!filters.line || filters.line==='vivienda')" :rows="filtered"/><div class="notice">Mejoramiento de Vivienda: el CSV declara SOLO_PLAN_TERRAZAS. Las asistencias técnicas ejecutadas no equivalen a obras terminadas. Ausencia de registros CVP no implica ausencia del Estado.</div></section>
        <template v-if="active==='ficha'"><TerritoryCard v-if="territory" :row="territory" :dataset="dataset"/><EmptyState v-else class="panel" title="Elige un territorio para conocer sus datos" description="Elige un territorio en el mapa o pulsa «Ver ficha» en la tabla."/></template>
        <section v-if="active==='metodologia'" class="panel methodology"><MethodologyPanel :dataset="dataset"/><FinalSourcesPanel v-if="dataset.status==='final'"/></section>
        <section v-if="active!=='metodologia' && active!=='panorama'" class="panel territories"><div class="panel-heading"><div><h2>Territorios</h2><p>{{ configured ? filtered.length : '—' }} territorios en la selección · {{ configured ? dataset.rows.length : '—' }} en el archivo</p></div><label class="sort-label">Ordenar<select aria-label="Ordenar territorios" v-model="order"><option value="name">Nombre del territorio</option><option value="need">Mayor necesidad primero</option></select></label></div><div v-if="shown.length" class="table-scroll"><table><caption class="sr-only">Territorios seleccionados y presencia por línea</caption><thead><tr><th>Territorio / código</th><th>Localidad</th><th>Tipo</th><th>Necesidad exploratoria</th><th>Integralidad</th><th v-for="l in lines" :key="l.key">{{ l.label }}</th><th>Consulta</th></tr></thead><tbody><tr v-for="r in shown" :key="String(get(r,'codigo'))"><th>{{ get(r,'nombre') }}<small class="block muted">{{ get(r,'codigo') }}</small></th><td>{{ get(r,'localidad') }}</td><td><span class="tag">{{ get(r,'tipo') }}</span></td><td>{{ format(need(r,dataset.rows,schema)) }}</td><td>{{ format(integral(r,schema)) }}</td><td v-for="l in lines" :key="l.key">{{ format(get(r,`registros_${l.key}`)) }}</td><td><button class="text-button" :aria-label="`Ver ficha de ${get(r,'nombre')}`" @click="select(String(get(r,'codigo')))">Ver ficha <ArrowUpRight :size="14"/></button></td></tr></tbody></table></div><EmptyState v-else :title="configured ? 'No hay territorios en esta selección' : 'El territorio espera sus datos'" :description="configured ? 'Prueba con otro nombre o limpia los filtros para ver más territorios.' : 'Carga un archivo CSV para consultar los indicadores y conocer su fuente.'"/><div class="pagination"><span>Resultados {{ shown.length ? (page-1)*10+1 : 0 }}–{{ Math.min(page*10,filtered.length) }} de {{ filtered.length }}</span><div><button class="icon-button" aria-label="Página anterior" :disabled="page<=1" @click="page--"><ChevronLeft :size="17"/></button><span>Página {{ page }} de {{ pages }}</span><button class="icon-button" aria-label="Página siguiente" :disabled="page>=pages" @click="page++"><ChevronRight :size="17"/></button></div></div></section>
        <footer class="footer"><span><strong>UBiK2</strong> · Caja de la Vivienda Popular</span><span>Observatorio territorial · {{ dataset.status==='final' ? 'Archivo final · lectura exploratoria' : 'Datos preliminares sujetos a validación' }}</span></footer>
      </main>
    </div>
  </div>
  <DataReadingGuide v-model="readingGuideOpen"/>
</template>
